questionvariables.text:
stack_include("contribl://prooflib.mac");
proof_steps: [
  ["hyp",     "Let \\(n\\) be an odd number."],
  ["intro",   "Then \\(n = 2k + 1\\) for some integer \\(k\\)."],
  ["alg",     "So \\(n^2 + 4n + 3 = (2k + 1)^2 + 4(2k + 1) + 3 = 4k^2 + 12k + 8 = 4(k + 1)(k + 2)\\)."],
  ["even",    "Since \\(k + 1\\) and \\(k + 2\\) are consecutive integers, one of them is even, so \\((k + 1)(k + 2) = 2m\\) for some integer \\(m\\)."],
  ["ded",     "So \\(n^2 + 4n + 3 = 4 \\times 2m = 8m\\), which is divisible by 8."],
  ["conc",    "Hence \\(n^2 + 4n + 3\\) is divisible by 8 for every odd number \\(n\\)."],
  ["d_every", "Then \\(n = 2k + 1\\) for every integer \\(k\\)."],
  ["d_circ",  "Assume that \\(n^2 + 4n + 3 = 8m\\) for some integer \\(m\\)."],
  ["d_check", "Since \\(1 + 4 + 3 = 8\\) and \\(9 + 12 + 3 = 24\\), the statement is true for every odd number \\(n\\)."]
];
proof_steps: random_permutation(proof_steps);
ta: proof("hyp", "intro", proof_c("alg", "even"), "ded", "conc");

feedbackvariables.text:
sa: parsons_decode(ans1);
sal: args(proof_flatten(sa));
[pd, saa]: proof_assessment(sa, proof_alternatives(ta));
has_circ: if member("d_circ", sal) then 1 else 0;
has_every: if member("d_every", sal) then 1 else 0;
has_check: if member("d_check", sal) then 1 else 0;
